    fun getAll(): List<GameQuestion> = part1() + part2()

    private fun q(ua: String, en: String, pl: String): GameQuestion {
        val a = AppLocale.t("🙋 Я", "🙋 Me", "🙋 Ja")
        val b = AppLocale.t("👉 Друг", "👉 Friend", "👉 Przyjaciel")
        return GameQuestion("WHO", AppLocale.t(ua, en, pl), a, b)
    }

